h-label"><?=$hasVideo?'Hover to play · Tap to preview':($hasReel?'Watch on Instagram':'Reel preview coming soon')?></span></div><?php if($hasVideo):?><button type="button" class="reel-preview-toggle" aria-label="Play <?=e($reel['brand'])?> preview" aria-pressed="false"><span class="reel-play-symbol">▶</span><span class="reel-stop-symbol">Ⅱ</span></button><?php else:?><span class="reel-external-symbol" aria-hidden="true">&nearr;</span><?php endif;?><div class="reel-playing-indicator" aria-hidden="true"><i></i><i></i><i></i><i></i><span>NOW PLAYING · MUTED</span></div></div><div class="reel-bottomline"><span><?=e($reel['subtitle'])?></span><a href="<?=e($destination)?>" target="_blank" rel="noopener" aria-label="Open <?=e($reel['brand'])?> <?=$hasReel?'reel':'Instagram profile'?>"><?php icon('instagram'); ?></a></div></article><?php endforeach;?></div><div class="reels-section-bottom"><span class="reels-brand-line">SOUND BLAST <i>✦</i> HERCULES <i>✦</i> TORPEDO <i>✦</i> FOCAL AUDIO</span><a class="text-link" href="<?=e($business['instagram'])?>" target="_blank" rel="noopener">See more on Instagram &nearr;</a></div></div></section>
